with parsed as (select id, created_at, coupon_codes, ship_to, attributes, ship_to.zip as ship_zip, size(filter(items, item -> item.qty >= 3)) as bulk_lines, exists(coupon_codes, c -> c like 'W%') as has_welcome_code from carts) select date_trunc('hour', created_at) as hour_window, count(*) as cnt, (unix_timestamp(max(created_at)) - unix_timestamp(min(created_at))) / 60 as span_minutes, count(*) as cnt_2, count(distinct id) as distinct_ids from parsed group by date_trunc('hour', created_at);
